CATS[0].s.push(
{t:"KORHOGO — Chirurgie · Examen blanc octobre 2025 (Version A) · QCD",d:"Appendicite, occlusion, hernie, Glasgow, fracture, luxation, cryptorchidie (Q1 à Q20)",qs:[
D("L'anorexie, les vomissements alimentaires et la constipation sont des signes annonciateurs ou prodromes de l'appendicite.",0,"Vrai. — Support : L2p108",null,"1"),
D("La septicémie à perfringens succède à un avortement provoqué.",0,"Vrai. — Support : L1p22",null,"2"),
D("L'invagination intestinale est l'une des causes mécaniques de l'occlusion intestinale.",0,"Vrai. — Support : L2p115",null,"3"),
D("La hernie inguinale est un épanchement liquidien dans le scrotum des testicules.",1,"Faux. — Support : L2p96",null,"4"),
D("Le pic de fréquence dans l'appendicite aigüe se situe entre 10 et 3 ans et concerne-les deux sexes.",1,"Faux. — Support : L2p106",null,"5"),
D("Les amphithroses sont des articulations immobiles.",1,"Faux. — Support : L3p5 (Doc TD en Chirurgie)",null,"6"),
D("Les occlusions inflammatoires sont la combinaison des occlusions mécaniques et celles qui sont fonctionnelles.",0,"Vrai. — Support : L2p116",null,"7"),
D("Les panaris du tissu cellulaire sous cutané sont des panaris superficiels.",1,"Faux. — Support : L1p26",null,"8"),
D("L'adénome de la prostate est une tumeur maligne qui se traduit par une hypertrophie de la glande prostatique.",1,"Faux (tumeur bénigne). — Support : L3p154",null,"9"),
D("La gangrène est un phlegmon nécrosant du tissu musculaire à évolution rapide et extensive.",0,"Vrai. — Support : L1p47",null,"10"),
D("La voie rhinopharyngée est une porte d'entrée du germe de l'ostéomyélite aigue.",0,"Vrai. — Support : L1p51",null,"11"),
D("Si l'abcès froid n'est pas fistulisé, il est nécessaire de procéder à l'incision large avec effondrement et destruction de la paroi à la curette.",1,"Faux. — Support : L1p36",null,"12"),
D("Le spina-bifida occulta ne se traite qu'en cas d'anomalies neurologiques graves.",0,"Vrai. — Support : L2p182",null,"13"),
D("Les occlusions fonctionnelles sont le fait du dérèglement du système nerveux intestinal.",0,"Vrai. — Support : L2p116",null,"14"),
D("Plus le score de Glasgow est élevé plus l'état du malade est grabataire.",1,"Faux. — Support : L3p5 (Doc neurochirurgie)",null,"15"),
D("Une fracture est une solution de continuité au niveau d'un os.",0,"Vrai. — Support : L1p62",null,"16"),
D("Lors d'un accident, la luxation antéro-interne est la variété la plus fréquente des luxations de l'épaule.",0,"Vrai.",null,"17"),
D("La péritonite peut avoir pour cause le bacille de Koch.",0,"Vrai.",null,"18"),
D("La température du scrotum est plus élevée que celle de l'abdomen.",1,"Faux. — Support : L2p171",null,"19"),
D("La cryptorchidie est une anomalie de la descente du testicule due à un défaut de sécrétion de testostérone.",0,"Vrai. — Support : L2p171",null,"20")
]},
{t:"KORHOGO — Chirurgie · Examen blanc octobre 2025 (Version A) · QCM",d:"Mal de Pott, péritonite, occlusion, rachis, hernies, Baxter, Glasgow, appendicite, brûlure (Q21 à Q38)",qs:[
M("Parmi les structures suivantes indiquez les deux qui sont affectées par le germe en cas de mal de Pott. L3p32 (Doc neurochirurgie)",["A. Les vertèbres","B. Les bronchioles","C. Les alvéoles pulmonaires","D. Les disques intervertébraux"],[0,3],"Le mal de Pott est une spondylodiscite tuberculeuse : vertèbres et disques intervertébraux.",null,"21"),
M("Indiquez les trois signes qui marquent la phase terminale d'une péritonite. L2p124",["A. Douleurs abdominales avec diffusion progressive (période initiale)","B. Vomissements bilieux, porracés et fécaloïdes","C. Températures et pouls variables (période initiale)","D. Hoquet","E. Immobilité diaphragmatique (période initiale)","F. Occlusion paralytique"],[1,3,5],"Phase terminale : vomissements bilieux, porracés et fécaloïdes, hoquet, occlusion paralytique. Les items A, C et E relèvent de la période initiale.",null,"22"),
M("Des quatre symptômes essentiels du syndrome occlusif, un seul signe physique caractérise l'occlusion, lequel ? L2p117",["A. Douleurs abdominales","B. Arrêt des matières et des gaz","C. Météorisme abdominal","D. Vomissement"],[2],"Le météorisme abdominal est le seul signe physique des quatre symptômes essentiels (les autres sont des signes fonctionnels).",null,"23"),
M("Les soins préopératoires pour la laparotomie consistent à : L2p127",["A. Prévenir l'hypovolémie à cause des pertes de liquides dues aux vomissements","B. Préparer la salle et le lit du malade","C. Préparer le champ opératoire","D. Contrôler le réveil physiologique"],[0,2],"Soins préopératoires : prévenir l'hypovolémie et préparer le champ opératoire. La salle, le lit et le réveil relèvent des suites opératoires.",null,"24"),
M("Toutes ces causes aboutissent à une occlusion mécanique, sauf une, laquelle ? L2p115",["A. Corps étrangers","B. Dérèglement du système nerveux intestinal","C. Torsion d'une anse intestinale sur elle-même","D. Invagination intestinale"],[1],"Le dérèglement du système nerveux intestinal entraîne une occlusion fonctionnelle, non mécanique.",null,"25"),
M("Deux de ces signes physiques indiquent une péritonite aigüe, lesquels ? L2p124",["A. Douleurs de la fosse iliaque droite","B. Contracture abdominale","C. Défense abdominale","D. Immobilité diaphragmatique","E. Accélération modérée du pouls","F. NFS à 10 000 éléments par mm3 de sang."],[1,3],"Signes physiques retenus : contracture abdominale et immobilité diaphragmatique.",null,"26"),
M("Parmi les propositions suivantes, indiquez celle qui se rapporte à la notion d'intervalle de temps libre chez le traumatisé crânien. L3p9 (Doc TD en Chirurgie)",["A. Le temps qui s'écoule entre la survenue de l'accident et la prise en charge du patient","B. Le temps qui sépare la perte de connaissance initiale et la réapparition des troubles de la conscience","C. La durée des troubles de la conscience occasionnée par le traumatisme crânien"],[1],"L'intervalle libre sépare la perte de connaissance initiale de la réapparition des troubles de la conscience (hématome extradural).",null,"27"),
M("Parmi les éléments suivants indiquez les trois signes d'une atteinte du rachis cervical en cas de traumatisme du rachis supérieur. L3p14 (Doc neurochirurgie)",["A. Les troubles sphinctériens","B. Les vertiges","C. La paresthésie","D. Les céphalées","E. Le torticolis","F. Les troubles neurovégétatifs"],[1,3,5],"Atteinte du rachis cervical supérieur : vertiges, céphalées et troubles neurovégétatifs.",null,"28"),
M("Parmi les propositions suivantes indiquez celle qui correspond à la durée moyenne du temps de guérison d'un patient sous traitement en cas de mal de POTT. L3p34(Doc neurochirurgie)",["A. 4 à 6 mois","B. 6 à 8 mois","C. 8 à 12 mois"],[2],"Durée moyenne du traitement et de la guérison du mal de Pott : 8 à 12 mois.",null,"29"),
M("Parmi les hernies suivantes, indiquez les deux qui sont des hernies de l'aine. L2p39",["A. La hernie ventrale latérale","B. La hernie inguinale","C. La hernie crurale","D. La hernie de la ligne blanche"],[1,2],"Les hernies de l'aine sont la hernie inguinale et la hernie crurale.",null,"30"),
M("Indiquez selon la règle de Baxter, le poids d'un brûlé à 50% de sa surface corporelle qui reçoit 9300 ml de soluté les deux premiers jours. L1p83",["A. 15,5 kg","B. 31 kg","C. 46,5 kg"],[1],"Baxter sur 2 jours : Q = 6 × Pds × SCB, donc Pds = 9300 / (6 × 50) = 31 kg.",null,"31"),
M("Parmi les paramètres suivants, indiquez les trois qui sont utilisés dans l'échelle de Glasgow. L3p3-4 (Doc neurochirurgie)",["A. La coloration de la peau","B. L'ouverture des yeux","C. La réponse verbale","D. Le mouvement des yeux","E. La réponse motrice","F. La sensibilité"],[1,2,4],"Échelle de Glasgow : ouverture des yeux, réponse verbale, réponse motrice.",null,"32"),
M("Parmi les actions suivantes, indiquez les deux à effectuer en urgence chez un patient qui souffre de rétention urinaire. L2p164",["A. L'adénomectomie","B. La cystectomie","C. La Ponction sus-pubienne","D. Le Sondage urétral"],[2,3],"En urgence, la rétention d'urine se traite par sondage urétral ou, s'il est impossible, par ponction sus-pubienne.",null,"33"),
M("Parmi les éléments suivants, indiquez les deux qui sont des formes anatomopathologiques de l'appendicite aigue. L2p107",["A. L'appendicite catarrhale","B. Le plastron appendiculaire","C. Les péritonites appendiculaires","D. Les appendicites gangreneuses"],[0,3],"Formes anatomopathologiques : appendicite catarrhale et appendicite gangreneuse. Plastron et péritonites sont des complications.",null,"34"),
M("Parmi les propositions suivantes indiquez les deux avantages du lever précoce pendant les suites opératoires.",["A. La prévention des chocs hémodynamiques","B. La lutte contre l'infection","C. L'accélération de la reprise du transit","D. La prévention des hémorragies","E. La prévention de la stase et l'obstruction bronchique"],[2,4],"Le lever précoce accélère la reprise du transit et prévient la stase et l'obstruction bronchique.",null,"35"),
M("Calculez le volume d'une poche de sang de concentré érythrocytaire devant passer en 2 heures avec un débit de 60 gouttes/min.",["A. 360 ml","B. 480 ml","C. 520 ml","D. 720 ml"],[1],"Q = (D × T en min) / 15 = (60 × 120) / 15 = 480 ml (en transfusion, 15 gouttes = 1 ml).",null,"36"),
M("Indiquer parmi ces propositions deux éléments pouvant être mis en évidence par l'ASP en cas d'occlusion. L2p118",["A. Gargouillement","B. Silence abdominal","C. Niveau hydro-aérique","D. Matité","E. Ballonnement abdominal","F. Siège de l'occlusion"],[2,5],"L'ASP met en évidence les niveaux hydro-aériques et le siège de l'occlusion.",null,"37"),
M("Ces évènements se succèdent lors d'une brûlure. Classer les par ordre chronologique<br>1. Exsudation plasmatique<br>2. Anoxie tissulaire<br>3. Hypovolémie<br>4. Trouble de la perméabilité capillaire<br>Indiquer votre classification parmi ces propositions. L1p78",["A. 1-2-3-4","B. 4-3-2-1","C. 1-4-3-2","D. 4-1-3-2"],[3],"Ordre chronologique : trouble de la perméabilité capillaire (4), exsudation plasmatique (1), hypovolémie (3), anoxie tissulaire (2).",null,"38")
]},
{t:"KORHOGO — Chirurgie · Examen blanc octobre 2025 (Version A) · Étude de cas N°1 (fractures)",d:"Fracture ouverte du fémur (A.S.) et fracture fermée de l'avant-bras (B.Y.) : gestes d'urgence, complications, plâtre, bloc opératoire (Q39 à Q51)",qs:[
M("Déclinez le geste d'urgence à poser avant l'évacuation des victimes. L2p42",["A. Réduction des fractures des victimes","B. Immobilisation provisoire des fractures des victimes"],[1],"Avant l'évacuation : immobilisation provisoire des fractures. La réduction est proscrite sur le lieu de l'accident.","<b>II- ETUDE DE CAS N°1</b><br>Infirmier(ère) Diplômé(e) d'Etat en service au centre de santé d'Assiè Akpessé, district sanitaire de M'Batto, vous êtes requis(e) par la brigade de gendarmerie de ladite ville pour un constat d'accident de la voie publique (AVP), ayant fait de nombreux blessés. A votre arrivée sur les lieux, vous suspectez chez monsieur A. S. l'une des victimes, une fracture ouverte de la diaphyse fémorale droite et chez madame B. Y. une fracture fermée des deux os de l'avant-bras droit.<br>Vous décidez d'évacuer les victimes au service de Chirurgie du CHR de Dimbokro.<br>A l'hôpital, les premières radiographies confirment le diagnostic de ces fractures ?","39"),
M("Enumérez trois buts de ce geste. L2p42",["A. Réduire la douleur","B. Arrêter une hémorragie","C. Minimiser le risque d'embolie graisseuse","D. Préparer l'ostéosynthèse","E. Eviter une ostéosynthèse","F. Limiter les déplacements des fragments osseux"],[0,2,5],"Buts de l'immobilisation provisoire : réduire la douleur, minimiser le risque d'embolie graisseuse, limiter les déplacements des fragments osseux.",null,"40"),
M("A quel type de squelette appartiennent ces fractures. (Anatomie L1)",["A. Squelette appendiculaire","B. Squelette principal","C. Squelette axial"],[0],"Fémur et avant-bras font partie du squelette appendiculaire (membres).",null,"41"),
M("Citez deux complications immédiates de la fracture ouverte de monsieur A.S. L3p41",["A. Ouverture du foyer de facture","B. Phlébite et embolie","C. Retard de consolidation","D. Choc traumatique et hémorragique","E. Atrophie musculaire","F. Raideur du genou"],[0,3],"Complications immédiates : ouverture du foyer de fracture et choc traumatique et hémorragique.",null,"42"),
M("Quelles sont les deux conséquences de ces complications ? L2p43",["A. Infection","B. Déshydratation","C. Amputation","D. Cal vicieux"],[0,2],"Conséquences : infection et amputation.",null,"43"),
M("En votre qualité d'Infirmier(ère) Diplômé(e) d'Etat, que feriez-vous pour minimiser ces complications ? (3 bonnes réponses) L2p43-44",["A. Pas de manœuvres ou de mobilisations intempestives","B. Faire la toilette générale du patient","C. Nettoyer la plaie aux antiseptiques soigneusement","D. Effectuer la prévention des escarres","E. Transporter rapidement, sans précipitation, le blessé dans un centre chirurgical","F. Réaliser une bonne prémédication"],[0,2,4],"Pas de mobilisation intempestive, nettoyage soigneux de la plaie aux antiseptiques, transport rapide sans précipitation vers un centre chirurgical.",null,"44"),
M("Expliquez le protocole de traitement des fractures de ces deux victimes. (3 bonnes réponses)",["A. Mobilisation","B. Réduction","C. Immobilisation provisoire","D. Education","E. Contention","F. Rééducation"],[1,2,5],"Protocole retenu : réduction, immobilisation provisoire et rééducation.",null,"45"),
M("Dès le retour de madame B.Y. du bloc opératoire, elle porte un plâtre au niveau du membre supérieur fracturé. Quel est le nom et la définition de ce plâtre ? L3p11 (Doc TD en chirurgie)",["A. Delbet de marche","B. Brachio-palmaire","C. Botte plâtrée","D. Minerve plâtrée"],[1],"Le plâtre brachio-palmaire immobilise le membre supérieur du bras à la paume.",null,"46"),
M("Enumérez trois (3) éléments de surveillance pour la prévention d'une éventuelle complication due à ce plâtre. L2p34",["A. Main gonflée et violacée","B. Prurit au niveau du membre atteint","C. Froideur des extrémités","D. Irréductibilité primitive du membre","E. Rotation par décalage des os lésés","F. Douleur plus ou moins vive dans l'avant-bras"],[0,2,5],"Surveillance du plâtre : main gonflée et violacée, froideur des extrémités, douleur dans l'avant-bras (risque de syndrome de Wolkmann).",null,"47"),
M("Décrivez la conduite à tenir en tant qu'Infirmier(ère) au bloc opératoire avant l'intervention. (3 bonnes réponses)",["A. Réaliser le Nursing","B. Préparer la chambre et le matériel pour l'hospitalisation","C. Préparer psychologiquement le client","D. Surveiller une survenue de syndrome de Wolkmann","E. Faire les prélèvements pour les examens préopératoires et les radiologies","F. Réaliser la prémédication"],[2,4,5],"Avant l'intervention : préparation psychologique, prélèvements pour les examens préopératoires et radiologies, prémédication.",null,"48"),
M("Identifiez deux (2) activités à réaliser en tant qu'Infirmier(ère) en hospitalisation de chirurgie pendant l'intervention.",["A. Réaliser le Nursing","B. Préparer la chambre et le matériel pour l'hospitalisation","C. Préparer psychologiquement le client","D. Surveiller une survenue de syndrome de Wolkmann","E. Faire les prélèvements pour les examens préopératoires et les radiologies","F. Rester l'intermédiaire entre les parents et le client"],[1,5],"Pendant l'intervention, en hospitalisation : préparer la chambre et le matériel, et rester l'intermédiaire entre les parents et le client.",null,"49"),
M("Identifiez deux (2) activités à réaliser en tant qu'Infirmier(ère) au bloc opératoire après l'intervention.",["A. Réaliser le Nursing","B. Préparer la chambre et le matériel pour l'hospitalisation","C. Préparer psychologiquement le client","D. Surveiller une survenue de syndrome de Wolkmann","E. Faire les prélèvements pour les examens préopératoires et les radiologies","F. Réaliser la prémédication"],[0,3],"Après l'intervention : réaliser le nursing et surveiller la survenue d'un syndrome de Wolkmann.",null,"50"),
M("La pose de la sonde urinaire se fait dans les cas suivants, sauf deux (02) ; lesquels ?",["A. Rétention d'urines","B. Douleur sus-pubienne","C. Infection urinaire","D. Hypertrophie bénigne de la prostate","E. Incontinence urinaire"],[2,4],"La sonde urinaire n'est pas posée en cas d'infection urinaire ni d'incontinence urinaire.",null,"51")
]},
{t:"KORHOGO — Chirurgie · Examen blanc octobre 2025 (Version A) · Étude de cas N°2 (hernie et transfusion)",d:"Patients A.S. (hernie, Hg 5 g/dl) et E.L. (contusion abdominale, Hg 4 g/dl) : calcul de transfusion, précautions (Q52 à Q60)",qs:[
M("De quoi souffre A.S. ?",["A. Hernie simple","B. Hernie étranglée"],[0],"Tuméfaction inguinale plus ou moins saillante traitée par traitement orthopédique, avec acte chirurgical retardé : hernie simple (non compliquée).","<b>IV- ETUDE DE CAS N° 2</b><br>L'équipe de garde dont vous faites partie reçoit deux patients :<br>➢ Patient 1 : A.S. 30 ans, pèse 60 kg, est reçu pour des douleurs abdominales accompagnées d'une sensation d'étirement et de gêne fonctionnel. Taux d'Hg = 5g/dl de sang.<br>➢ Patient 2 : E.L., 42 ans, 65 kg, vient pour une contusion abdominale. Taux d'hémoglobine = 4 g/dl de sang.<br>Le chirurgien pratique un examen physique qui révèle une tuméfaction inguinale plus ou moins saillante chez M. A.S. et lui prescrit un traitement orthopédique tout en retardant L'acte chirurgical.<br>Il préconise avant les interventions chirurgicales, le relèvement des taux d'hémoglobine des deux malades à 10 g/dl de sang, sachant que le temps d'administration est de trois heures et demie avec du concentré érythrocytaire.","52"),
M("Quelle est la complication majeure de cette affection ?",["A. Péritonite aigue","B. Etranglement","C. Occlusion intestinale"],[1],"La complication majeure de la hernie est l'étranglement.",null,"53"),
M("Quelle serait la conduite à tenir si vous receviez M. A.S. dans un centre de santé rural en cas de cette complication majeure et si l'accident n'est pas récent ?",["A. Accueillir le client avec bienveillance et l'enregistrer","B. Réduire la hernie","C. Prendre les constantes (température, pouls, tension artérielle)","D. Réaliser l'incision","E. L'examiner pour s'assurer qu'il s'agit effectivement de l'affection","F. Faire la prémédication"],[0,2,4],"Accueil, enregistrement, prise des constantes et examen pour confirmer l'étranglement. La réduction et l'incision relèvent du chirurgien (accident non récent).",null,"54"),
M("Calculez la quantité et le débit de sang à transfuser à AS.",["A. 900 ml","B. 128 gouttes/mn","C. 1800 ml","D. 64 gouttes/mn"],[1,2],"Quantité = (Hb désirée − Hb du patient) × poids × 6 = (10 − 5) × 60 × 6 = 1800 ml. Débit = (1800 × 15) / (3,5 × 60) = 128 gouttes/mn (formule de l'épreuve : (Hb désirée − Hb du patient) × poids × 6).",null,"55"),
M("Calculez la quantité et le débit de sang à transfuser à E.L.",["A. 2340 ml","B. 1170 ml","C. 84 gouttes/mn","D. 167 gouttes/mn"],[0,3],"Quantité = (10 − 4) × 65 × 6 = 2340 ml. Débit = (2340 × 15) / (3,5 × 60) = 167 gouttes/mn (formule de l'épreuve : (Hb désirée − Hb du patient) × poids × 6).",null,"56"),
M("Enumérez les mécanismes de survenue des contusions abdominales. (3 réponses justes)",["A. Choc direct","B. Percussion","C. Par effet explosif","D. Décélération","E. Choc indirect","F. Etirement"],[0,3,4],"Mécanismes des contusions abdominales : choc direct, décélération, choc indirect.",null,"57"),
M("Expliquez deux (2) précautions à prendre avant la transfusion sanguine chez ces deux patients.",["A. Informer le patient de l'imminence du soin","B. Surveiller les réactions du patient (calme, agitations, plaintes)","C. Surveiller son faciès (sudation excessive)","D. Surveiller la diurèse sur les 24H et l'apparition de Fièvre","E. Réaliser la traçabilité et garder le flacon vide pendant 2 heures au moins","F. Réaliser le test ultime au lit du malade"],[0,5],"Avant la transfusion : informer le patient de l'imminence du soin et réaliser le test ultime au lit du malade.",null,"58"),
M("Identifiez deux (2) précautions à prendre pendant la transfusion sanguine chez les deux patients.",["A. Informer le patient de l'imminence du soin","B. Réaliser le test ultime au lit du malade","C. Surveiller les réactions du patient (calme, agitations, plaintes)","D. Surveiller son faciès (sudation excessive)","E. Surveiller la diurèse sur les 24H et l'apparition de Fièvre","F. Réaliser la traçabilité"],[2,3],"Pendant la transfusion : surveiller les réactions du patient et son faciès (sudation excessive).",null,"59"),
M("Expliquez les précautions à prendre après la transfusion sanguine chez les deux patients.",["A. Informer le patient de l'imminence du soin","B. Réaliser le contrôle ultime au lit et régler le débit","C. Surveiller les réactions du patient (calme, agitations, plaintes)","D. Surveiller son faciès (sudation excessive)","E. Surveiller la diurèse sur les 24H et l'apparition de Fièvre","F. Réaliser la traçabilité"],[4,5],"Après la transfusion : surveiller la diurèse sur 24 h et l'apparition de fièvre, et réaliser la traçabilité.",null,"60")
]}
);
CATS[1].s.push(
{t:"KORHOGO — Médecine · Examen blanc N°1 L3 2025 · Cas clinique Mlle Kouassi (ulcère)",d:"Hémorragie digestive : diagnostic, examen, rôle de l'infirmier (Q1 à Q4)",qs:[
M("Choisissez votre hypothèse diagnostique parmi ces pathologies. L2p68 (Doc de médecine) / L1p29 (Doc de sémio médical)",["A. Rupture des varices œsophagiennes","B. Dysenterie amibienne","C. Ulcère gastroduodénal"],[2],"Douleurs postprandiales à type de brûlure et de crampe, épigastriques, nocturnes, puis selles noirâtres et vomissements de sang après diclofénac : ulcère gastroduodénal.","<b>QCM CAS CLINIQUE</b><br>En service aux urgences médicales du CHR de Korhogo, vous recevez ce jour Mlle Kouassi Eliane 21 ans étudiante en licence 3 département de lettre moderne à l'université peleforo gbon pour des douleurs abdominales aigues depuis trois jours. L'interrogatoire effectué par le médecin révèle les caractéristiques de cette crise à savoir : <u>douleurs postprandiales à type de brulure et de crampe, de siège épigastrique</u> survenant le plus souvent la nuit. Elle précise également qu'en raison de l'intensité de la douleur elle a consommé deux comprimés de diclofenac 50 mg. Depuis lors, <u>elle émet des selles noirâtres et fétides</u> parfois des vomissements de sang passagers. <u>Mlle Kouassi étant hospitalisé est stressée et angoissée</u> parce qu'elle réfléchit à son examen de fin année dont la date de composition est proche. Aussi, elle pose des questions relatives à sa maladie.","1"),
M("Choisissez parmi ces examens, celui qui est indiqué pour confirmer le diagnostic de cette affection. L2p70 (Doc de medecine) / L1p29 (Doc de sémio médical)",["A. Examen parasitologique des selles","B. Fibroscopie digestive","C. Echographie abdominale"],[1],"La fibroscopie digestive confirme l'ulcère gastroduodénal.",null,"2"),
M("Parmi les propositions ci-après, relevez deux rôles de l'infirmer.",["A. Prescrire des hémostatiques","B. Préparer la patiente pour les examens appropriés","C. Prendre rendez-vous auprès du service concerné","D. Prescrire des macro molécules pour pallier un état de choc"],[1,2],"Rôles de l'infirmier : préparer la patiente pour les examens et prendre rendez-vous auprès du service concerné. Les prescriptions relèvent du médecin.",null,"3"),
M("Précisez la nature de l'hémorragie digestive parmi ces propositions. L1p32(Doc de sémio médical)",["A. Haute","B. Basse"],[0],"Hématémèse et mélaena : hémorragie digestive haute.",null,"4")
]},
{t:"KORHOGO — Médecine · Examen blanc N°1 L3 2025 · QCM",d:"Hématémèse, Henderson, thrombose, ulcère, hépatite, bilharziose, HTA, TDR, ARV, escarres, rage, vers, lavage d'oreille, positions (Q5 à Q40)",qs:[
M("Choisissez parmi ces propositions le terme d'une émission de sang par la bouche. L1p32(Doc de sémio médical)",["A. Une Hématémèse","B. Un Mélaena","C. Une Hémoptysie"],[0],"Une émission de sang par la bouche (vomissement de sang) est une hématémèse. Le mélaena est une émission de sang digéré par l'anus ; l'hémoptysie est une expectoration de sang d'origine respiratoire.",null,"5"),
M("Relevez parmi les propositions ci-après le besoin prioritaire de Mlle KOUASSI selon le modèle conceptuel de VIRGINIA Henderson.",["A. Besoin de communiquer","B. Besoin d'apprendre","C. Besoin de se mouvoir et adopter une position convenable."],[1],"Mlle Kouassi, hospitalisée, est stressée et pose des questions sur sa maladie : son besoin prioritaire selon Virginia Henderson est le besoin d'apprendre.",null,"6"),
M("M. BP 70 ans, hospitalisé depuis 72 heures suite à une intervention chirurgicale présente ce jour une inflammation de la jambe gauche caractérisée par une douleur au mollet, un œdème dur ne prenant pas le godet, la peau est chaude et luisante ; Choisissez parmi ces pathologies votre hypothèse diagnostique. L2p10 (Doc de médecine)",["A. Une sciatique","B. Un abcès chaud","C. Une thrombose veineuse"],[2],"Douleur du mollet, œdème dur ne prenant pas le godet, peau chaude et luisante après chirurgie : thrombose veineuse.",null,"7"),
M("Relevez parmi ces pathologies celle qui se complique souvent en une hémorragie digestive. L2p65 (Doc de médecine)",["A. Reflux gastroœsophagien","B. Ulcère gastroduodénal","C. Gastrite"],[1],"L'ulcère gastroduodénal se complique souvent d'hémorragie digestive.",null,"8"),
M("Choisissez parmi ces examens paracliniques celui qui permet de diagnostiquer une hépatite. L2p39(Doc de médecine)",["A. Echographie du foie","B. Sérologie","C. NFS"],[1],"La sérologie permet de diagnostiquer une hépatite virale.",null,"9"),
M("Parmi les propositions ci-après relevez celle qui est contre-indiquée dans le cas d'une aspiration gastrique.",["A. Perforation de l'estomac","B. Cancer de l'estomac","C. Lavage d'estomac"],[0],"La perforation de l'estomac contre-indique l'aspiration gastrique.",null,"10"),
M("Parmi ces trois (3) affections cardiaques, cocher celle du myocarde. L2p16(Doc de médecine)",["A. Angine de poitrine","B. Insuffisance ventriculaire gauche","C. Embolie pulmonaire"],[0],"L'angine de poitrine est une pathologie du myocarde (L2p16).",null,"11"),
M("Parmi ces propositions suivantes, relevez celle qui correspond à l'hématurie due à la bilharziose urogénitale. L1p18(Doc de maladie infectieuse)",["A. Hématurie Initiale","B. Hématurie Totale","C. Hématurie Terminale"],[2],"L'hématurie de la bilharziose urogénitale est terminale.",null,"12"),
M("Choisissez parmi ces pathologies celle qui est provoquée par Schistosoma Haematobium. L1p14(Doc de maladie infectieuse)",["A. Bilharziose Intestinale avec complications hépatiques","B. Bilharziose Uro-génitale","C. Bilharziose Rectale et génitale"],[1],"Schistosoma haematobium provoque la bilharziose uro-génitale.",null,"13"),
M("Cochez les deux facteurs de risques de la thrombose veineuse profonde des membres inférieurs dans les propositions ci-dessous :",["A. Le surpoids","B. Immobilisation suite à un accident","C. Le diabète","D. Insuffisance veineuse chronique","E. L'œdème des membres inférieurs"],[1,3],"Facteurs de risque retenus : immobilisation suite à un accident et insuffisance veineuse chronique.",null,"14"),
M("Relevez 2 signes généraux de la tuberculose pulmonaire parmi les manifestations cliniques ci-après. L1p107(Doc de sémio médical)",["A. Asthénie","B. Anorexie","C. Toux nocturne de plus de 2 semaines","D. Amaigrissement"],[0,3],"Signes généraux : asthénie et amaigrissement. La toux est un signe fonctionnel respiratoire.",null,"15"),
M("Choisissez parmi ces propositions, l'intervalle de temps recommander pour réaliser l'examen bactériologique de suivi après initiation au traitement antituberculeux.",["A. 20 jours à 2 mois après le début du traitement","B. 10 à 20 jours après le début du traitement","C. 15 à 30 jours après le début traitement"],[0],"Réponse relevée sur la correction de l'épreuve : A.",null,"16"),
M("Choisissez la bonne réponse. Le germe isolé en cas d'une péricardite est : L2p28(Doc de médecine)",["A. Le bacille de koch","B. La salmonella typhi","C. Le pneumocoque"],[2],"Réponse relevée sur la correction de l'épreuve : le pneumocoque.",null,"17"),
M("Parmi ces propositions, cocher deux moyens de prévention des phlébites dans thrombose veineuse profonde des membres inférieurs. L2p11(Doc de médecine)",["A. Détruire le thrombus","B. Mobilisation active","C. Lever précoce","D. Repos strict"],[1,2],"Prévention des phlébites : mobilisation active et lever précoce.",null,"18"),
M("Choisissez parmi ces propositions celle qui répond au concept de la double protection. L1p27(Doc de COURS DE VIH SIDA)",["A. Contre les grossesses à risque et les IST/VIH/Sida","B. Contre les grossesses non désirées et les IST","C. Contre les grossesses non désirées et les IST-VIH/Sida"],[2],"La double protection protège contre les grossesses non désirées et contre les IST-VIH/Sida.",null,"19"),
M("L'HTA se complique sur trois organes, indiquez la bonne réponse parmi ces propositions. L2p5(Doc de médecine)",["A. Le cerveau, le cœur et les reins","B. Le foie, le pancréas et les poumons","C. Les poumons, le foie et le cœur"],[0],"L'HTA se complique sur le cerveau, le cœur et les reins.",null,"20"),
M("Choisissez parmi les dates suivantes, celle qui correspond à l'avènement de la gratuité des ARV en Côte d'Ivoire. L1p33(Doc de COURS DE VIH SIDA)",["A. 20 Août 2008","B. 20 Août 2004","C. 20 Août 2003"],[0],"Réponse relevée sur la correction de l'épreuve : 20 août 2008.",null,"21"),
M("Indiquez parmi les propositions suivantes celle qui répond à la définition de l'équilibre entre la production et la perte de température par l'organisme. L1p47(Doc de METHODE ET TECHNIQUE DE SOINS INFIRMIERS)",["A. La thermogenèse","B. La thermolyse","C. La thermorégulation"],[2],"Thermogenèse = production de la chaleur ; thermolyse = déperdition de la chaleur ; thermorégulation = équilibre entre les deux.",null,"22"),
M("Selon la classification européenne, Indiquez le stade de l'évolution des escarres lorsqu'il y a apparition d'ulcération jaunâtre fibrineuse. L1p129(Doc de METHODE ET TECHNIQUE DE SOINS INFIRMIERS)",["A. Stade 1","B. Stade 2","C. Stade 3"],[2],"Stade 1 = érythème ; stade 2 = atteinte de l'épiderme et du derme ; stade 3 = ulcération jaunâtre fibrineuse.",null,"23"),
M("Indiquez le débit d'une perfusion d'un soluté de 500ml à passer en 4 heures parmi ces propositions.",["A. 41 gouttes/min","B. 50 gouttes/min","C. 30 gouttes/min"],[0],"D = (Q × 20) / (T × 60) = (500 × 20) / (4 × 60) = 41,66 ≈ 41 gouttes/min.",null,"24"),
M("Indiquez le débit d'une transfusion 450 ml à passer en 2 heures dans cette liste.",["A. 40 gouttes/min","B. 56 gouttes/min","C. 30 gouttes/min","D. "],[1],"D = (Q × 15) / (T × 60) = (450 × 15) / (2 × 60) = 56,25 gouttes/min.",null,"25"),
M("Parmi ces troubles mictionnels, indiquez celle qui correspond à Une miction fréquente peu abondante. L1p39(Doc de sémio médical)",["A. Une dysurie","B. Une pollakiurie","C. Une oligurie"],[1],"La pollakiurie est une miction fréquente et peu abondante.",null,"26"),
M("Indiquer parmi ces propositions le diagnostic de la rage.",["A. La biologie","B. La clinique","C. La biologie et la clinique"],[1],"Le diagnostic de la rage est clinique.",null,"27"),
M("Indiquez dans cette liste la proposition qui correspond aux différentes formes au cours de la rage. L1p122(Doc de maladie infectieuse)",["A. 3 formes cliniques","B. 2 formes cliniques","C. 1 forme clinique"],[0],"Trois formes : spastique (furieuse), paralytique (muette ou tranquille) et démentielle.",null,"28"),
M("Parmi ces propositions, choisissez celle qui correspond à la définition de la dysenterie. L1p30 (Doc de sémio médical) / L1p47(Doc de maladie infectieuse)",["A. Sang dans les selles qui sont peu abondantes","B. Sang et de glaire dans les selles peu abondantes","C. Glaire peu abondante et de sang dans les selles"],[1],"La dysenterie : selles peu abondantes contenant du sang et de la glaire.",null,"29"),
M("Choisissez l'indication principale du lavage d'oreille parmi ces éléments. L3p55(Doc de COURS ORL)",["A. Bouchon de cérumen","B. Otite suppurée","C. Otalgie (Douleur forte)"],[0],"L'indication principale du lavage d'oreille est le bouchon de cérumen.",null,"30"),
M("Choisissez parmi ces propositions celle qui est interdite pour un lavage d'oreille. L3p56(Doc de COURS ORL)",["A. Perforation du tympan","B. Acouphène","C. Présence de Corps étranger"],[0],"La perforation du tympan contre-indique le lavage d'oreille.",null,"31"),
M("Choisissez parmi ces signes, celui qui peut survenir au cours du lavage d'oreille. L3p57(Doc de COURS ORL)",["A. Vertiges","B. Céphalées","C. Fièvre"],[0],"Des vertiges peuvent survenir pendant le lavage d'oreille.",null,"32"),
M("Indiquez le nom scientifique des vers ronds parmi ces propositions. L1p20(Doc de maladie infectieuse)",["A. Nématodes","B. Cestodes","C. Trématodes"],[0],"Les vers ronds sont les nématodes.",null,"33"),
M("Choisissez la caractéristique principale de l'ascaris dans cette liste. L1p20(Doc de maladie infectieuse)",["A. Ver Plat","B. Ver Rond","C. Ver Ovale"],[1],"L'ascaris est un ver rond.",null,"34"),
M("Choisissez parmi ces vers, deux qui se contractent en pénétrant la peau. L1p20(Doc de maladie infectieuse)",["A. Ascaris","B. Anguillule","C. Ankylostome","D. Le ver de Guinée"],[1,2],"L'anguillule et l'ankylostome pénètrent par la peau.",null,"35"),
M("Choisissez parmi ces vers, celui qui provoque des démangeaisons anales intenses la nuit chez l'enfant. L1p31(Doc de maladie infectieuse)",["A. Dracunculose","B. Oxyure","C. Ascaris"],[1],"L'oxyure provoque un prurit anal nocturne chez l'enfant.",null,"36"),
M("Cocher une complication de l'artériopathie oblitérante des membres inférieurs parmi les propositions ci-dessous.",["A. Dermite","B. Occlusion artérielle aigue","C. Ongle cassante"],[1],"L'occlusion artérielle aiguë est une complication de l'artériopathie oblitérante des membres inférieurs.",null,"37"),
M("Madame F, 88 ans, vous demande de l'accompagner à la salle à manger. Elle se déplace avec une canne. Choisissez parmi ces propositions le positionnement de madame F.",["A. La position physiologique","B. La position antalgique","C. La position thérapeutique"],[0],"Madame F marche (avec une canne) : elle est en position physiologique. La position antalgique soulage une douleur ; la position thérapeutique est prescrite pour un traitement.",null,"38"),
M("Choisissez l'installation convenable pour les personnes présentant des difficultés cardio-respiratoires.",["A. Installation Dorsale","B. Installation Latérale","C. Installation Assise"],[2],"Les difficultés cardio-respiratoires imposent l'installation assise.",null,"39"),
M("Parmi les propositions suivantes choisissez la position dite « Semi-Fowler à 30° »",["A. Tête en hauteur","B. Tête en bas","C. Tête et pieds relevés"],[0],"Semi-Fowler à 30° : patient allongé, tête et thorax relevés (tête en hauteur) à environ 30°.",null,"40")
]},
{t:"KORHOGO — Médecine · Examen blanc N°1 L3 2025 · QCD",d:"Thrombose, insuffisance cardiaque, hépatites, fièvre typhoïde, rougeole, rage, tétanos, journées mondiales (Q41 à Q60)",qs:[
D("La thrombose veineuse profonde des membres inférieurs est la complication de l'embolie pulmonaire.",1,"Faux. C'est l'embolie pulmonaire qui est la complication de la thrombose veineuse profonde.",null,"41"),
D("Les signes cliniques de <u>l'insuffisance ventriculaire gauche</u> sont dominés par les signes de stases.",1,"Faux. Correction : « insuffisance ventriculaire droite ». — Support : L2p23 (Doc de médecine)",null,"42"),
D("L'angine de poitrine est une pathologie du myocarde.",0,"Vrai. — Support : L2p16 (Doc de médecine)",null,"43"),
D("<u>Lyser</u> le thrombus est un but de la thrombose veineuses des membres inférieurs.",0,"Vrai. Le livre précise : « détruit ».",null,"44"),
D("L'hépatite A peut se contracter au cours des rapports sexuels.",1,"Faux. — Support : L2p36 (Doc de médecine)",null,"45"),
D("Le mode de contamination de l'hépatite A est direct et indirect.",0,"Vrai.",null,"46"),
D("Les complications de la fièvre typhoïde sont présentes à la phase d'invasion de la maladie.",1,"Faux. — Support : L1p90 (Doc de maladie infectieuse)",null,"47"),
D("Le signe de koplick dans la rougeole se définit comme étant de petites taches blanchâtres à l'intérieur de la joue de l'enfant rougeoleux.",0,"Vrai.",null,"48"),
D("La chronologie de l'apparition des boutons au cours de la rougeole est des pieds à la tête.",1,"Faux.",null,"49"),
D("La rage est contagieuse.",0,"Vrai.",null,"50"),
D("Les hépatites sont classées en deux catégories.",1,"Faux. Correction : « Virale, Médicamenteuse, alcoolique ».",null,"51"),
D("La journée mondiale du diabète a lieu chaque année du 14 octobre.",1,"Faux. Correction : 14 NOVEMBRE.",null,"52"),
D("La journée mondiale de la lutte contre le paludisme a lieu chaque année du 25 Avril.",0,"Vrai.",null,"53"),
D("La journée mondiale de lutte contre la faim est célébrée le 15 Juin de chaque année.",1,"Faux. La Journée mondiale de l'alimentation (lutte contre la faim) est célébrée le 16 octobre.",null,"54"),
D("Les signes de la fièvre Typhoïde au premier septénaire sont : Céphalées, Insomnie, Vomissement, Epistaxis, Température élevée. (CIVET)",1,"Faux. — Support : L1p89 (Doc de maladie infectieuse)",null,"55"),
D("Le moustique impliqué dans la transmission de la fièvre jaune pique aussi bien la nuit que le jour.",1,"Faux. Correction : « la journée ». — Support : L1p127 (Doc de maladie infectieuse)",null,"56"),
D("Le tétanos est une toxiinfection <u>contagieuse et non immunisante</u>.",1,"Faux. Correction : « non contagieuse et non immunisante ». — Support : L1p109 (Doc de maladie infectieuse)",null,"57"),
D("L'Opisthotonos s'observe à la période d'état de la méningite purulente.",1,"Faux. — Support : L1p110 (Doc de maladie infectieuse)",null,"58"),
D("Coronavirus est un virus à ARN.",0,"Vrai. — Support : L1p94 (Doc de maladie infectieuse)",null,"59"),
D("La péricardite aigue est l'inflammation <u>d'un feuillet</u> du péricarde associé ou non à la présence d'un épanchement liquidien.",1,"Faux. Correction : « deux feuillets ». — Support : L2p28 (Doc de médecine)",null,"60")
]}
);
CATS[2].s.push(
{t:"KORHOGO — Pédiatrie · Examen blanc octobre 2025 (1er sujet, IDE/SFM) · QCD",d:"Marasme, sevrage, ocytocine, infection néonatale, hypothermie, toise, paludisme grave, malnutrition (Q1 à Q15)",qs:[
D("Le marasme est provoqué par une insuffisance d'apport micronutriments. L3p57",1,"Faux. Le marasme est entraîné par un déficit en nutriment de type 2.",null,"1"),
D("Le sevrage définitif avant 24 mois est un facteur favorisant le déficit en macronutriments.",1,"Faux. C'est un facteur favorisant le déficit en micronutriments (vitamines et sel).",null,"2"),
D("Les cellules épithéliales du sein sont les cibles de l'hormone ocytocine",1,"Faux. L'ocytocine est l'hormone d'éjection du lait maternelle en agissant sur les cellules myoépithéliales.",null,"3"),
D("Au cours de la malnutrition aigüe, on observe un excès global et homogène en nutriment. L3p57",1,"Faux. On observe un déficit global et homogène en nutriment.",null,"4"),
D("Les aliments énergétiques aident les enfants à effectuer toutes sortes d'activités physiques.",0,"Vrai. Aliments énergétiques = glucides et lipides.",null,"5"),
D("Les aliments de croissance ou de construction protègent contre les maladies.",1,"Faux. Plutôt les aliments de protection protègent contre les maladies.",null,"6"),
D("BK né à terme est à j2 de vie et présente une infection bactérienne néonatale. L'infection de BK est d'origine maternelle. L3p17",0,"Vrai. Infection bactérienne néonatale précoce ou materno-fœtale J0-J7.",null,"7"),
D("Le nouveau-né BK à une température à 35° Celsius. Il présente une infection. L'hypothermie est un signe fréquent de l'infection bactérienne néonatale. L3p19",0,"Vrai. Principaux problèmes du nouveau-né infecté : hypothermie, difficulté d'alimentation, résistance des germes aux antibiotiques usuels, décès.",null,"8"),
D("Pour traiter l'hypothermie du nouveau-né BK, je le place en incubateur (couveuse). Cet acte de soins fait partie du rôle de conseils et prévention de l'agent de santé. L3p19",1,"Faux. Plutôt un rôle propre (le livre indique : « Plutôt un rôle »).",null,"9"),
D("Pendant l'hospitalisation, le nouveau-né BK présente une détresse respiratoire avec un indice de Silverman à 7. Pour la prise en charge, l'infirmier major vous conseille de ne pas le gaver. Ce conseil est pertinent",0,"Vrai. Score de Silverman à 7 : détresse respiratoire grave.",null,"10"),
D("Jusqu'à 2 ans, j'utilise une toise verticale pour la mesure de la taille de l'enfant. L3p32",1,"Faux. Toise horizontale avant 2 ans, toise verticale après.",null,"11"),
D("En Côte d'ivoire, pour traiter le paludisme grave en 2025, les directives nationales préconisent d'utiliser en première intention l'artésunate per os. L3p52",1,"Faux. Plutôt intraveineuse / intramusculaire.",null,"12"),
D("Le nourrisson JC présente un muguet buccal. Pour réaliser ses soins buccaux, j'utilise du sérum bicarbonaté dosé à 14 pour 1000. (L1p18 Soins aux enfants)",0,"Vrai. Sérum bicarbonaté à 14 pour 1000 ou 14 ‰ ou 1,4 %.",null,"13"),
D("Mme ZW doit reprendre le service après son congé de maternité. Pour nourrir son enfant, L'agent de santé conseille la poursuite de l'allaitement exclusif. Le conseil de l'agent de santé est impertinent.",1,"Faux. Le conseil est plutôt pertinent.",null,"14"),
D("Le nourrisson KKA souffre d'une malnutrition aigüe sévère. Je lui administre à l'admission de l'eau sucrée dans l'attente du lait thérapeutique.",0,"Vrai.",null,"15")
]},
{t:"KORHOGO — Pédiatrie · Examen blanc octobre 2025 (1er sujet, IDE/SFM) · QCM",d:"Période néonatale, allaitement, convulsions, paludisme, malnutrition, Z-score, état de mal convulsif (Q16 à Q47)",qs:[
M("La période néonatale précoce s'étend de :",["A. Jour 0 à jour 30","B. Jour 0 à jour 07","C. Jour 0 à jour 28","D. Jour 0 à jour 17"],[1],"La période néonatale précoce s'étend du jour 0 au jour 7.",null,"16"),
M("Le vernix caseosa est :",["A. Le fin duvet recouvrant les épaules et le dos du prématuré","B. Une hypertrophie des glandes sébacées.","C. Un enduit gras recouvrant presque tout le corps","D. Des taches sur le visage du nouveau-né"],[2],"Le vernix caseosa est un enduit gras recouvrant presque tout le corps du nouveau-né.",null,"17"),
M("Parmi la liste d'hormone ci-dessous, cochez l'hormone responsable l'éjection du lait dans les seins",["A. L'ocytocine","B. La progestérone","C. L'estrogène","D. La prolactine"],[0],"L'ocytocine est responsable de l'éjection du lait.",null,"18"),
M("Parmi les propositions suivantes, cochez la proposition qui fait partie des critères d'une bonne prise de sein",["A. Le menton touche l'aréole et les succions sont profondes et lentes entrecoupées de pauses","B. La bouche est grande ouverte et la lèvre inférieure est éversée vers l'extérieur","C. L'aréole est plus visible en-dessous qu'au-dessus de la bouche","D. On entend l'enfant déglutir le lait maternel"],[1],"Réponse relevée sur la correction de l'épreuve : bouche grande ouverte et lèvre inférieure éversée vers l'extérieur.",null,"19"),
M("Lors d'une séance de diététique, au centre de santé, recommande aux l'agent santé mères, l'ablactation chez le nourrisson à partir de l'âge de :",["A. 6 mois","B. 12 mois","C. 18 mois","D. 24 mois"],[0],"L'ablactation (diversification alimentaire) commence à 6 mois.",null,"20"),
M("Dans la malnutrition aigüe sévère avec complications l'enfant",["A. est très éveillé","B. a un bon appétit","C. manifeste de l'intérêt","D. a œdèmes bilatéraux"],[3],"La malnutrition aiguë sévère avec complications s'accompagne notamment d'œdèmes bilatéraux (enfant apathique, sans appétit).",null,"21"),
M("Agent de santé au service de pédiatrie du CHU D'ANGRE, vous recevez, en urgence un nourrisson présentant des convulsions. Les gestes d'urgence à poser sont :",["A. Mettre le nourrisson en décubitus dorsal et le ventiler","B. Mettre le nourrisson en position latérale de sécurité et arrêter les crises en lui administrant 0,5mg - 1mg/kg de Diazépam par voie intra rectale","C. Mettre le nourrisson en position latérale de sécurité et arrêter les crises en lui administrant 2-3 mg/kg de Diazépam par voie intramusculaire","D. Mettre le nourrisson en décubitus ventral pour libérer les voies aériennes supérieures."],[1],"Position latérale de sécurité et diazépam intrarectal 0,5 à 1 mg/kg.",null,"22"),
M("Devant la crise convulsive du nourrisson, le soin délégué de l'agent de santé se résume à :",["A. Administrer le traitement prescrit par le médecin","B. Assister le médecin à la réalisation de la ponction lombaire","C. Accompagner le nourrisson chez le spécialiste","D. Acheminer les prélèvements au Laboratoire"],[0],"Le soin délégué est l'administration du traitement prescrit par le médecin.",null,"23"),
M("Pour confirmer le diagnostic du paludisme simple, l'agent de santé",["A. Réalise au lit du patient, un test de diagnostic rapide","B. Réalise au lit du patient, une goutte épaisse","C. Réalise au lit du patient, un frottis sanguin","D. Réalise au lit du patient, une numération formule sanguine"],[0],"Le diagnostic du paludisme simple se confirme par un test de diagnostic rapide (TDR) au lit du patient.",null,"24"),
M("BH est né à terme avec un poids de naissance à 3750 grammes, son poids à l'âge de 24 mois est le suivant :",["A. 12Kg","B. 13Kg","C. 14Kg","D. 15 Kg"],[3],"Poids à 24 mois = PN × 4 = 3,750 × 4 = 15 kg.",null,"25"),
M("Lorsque l'agent de santé est en exercice dans un établissement sanitaire de premier contact, ses soins propres en cas de paludisme grave sont :",["A. Accueillir l'enfant et organiser la référence","B. Administrer l'antipaludique, et mettre l'enfant en observation","C. Appeler le médecin pour le traitement à faire","D. Participer à la réalisation du bilan biologique"],[0],"Au premier contact, l'agent de santé accueille l'enfant et organise la référence.",null,"26"),
M("La malnutrition aigüe sévère sans complication est prise en charge",["A. Unité nutritionnelle thérapeutique","B. Unité nutritionnelle thérapeutique ambulatoire","C. Unité nutritionnelle de supplémentation","D. Unité nutritionnelle thérapeutique et à domicile"],[1],"La malnutrition aiguë sévère sans complication est prise en charge en unité nutritionnelle thérapeutique ambulatoire.",null,"27"),
M("L'enfant ayant le marasme présente les signes cliniques suivants :",["A. Cheveux roux, cassants clairsemés","B. Peau sèche, craquelée, et dépigmentée","C. Un visage creusé, vieillot avec un regard vif et intéressé","D. Anorexie"],[2],"Le marasme donne un visage creusé, vieillot, avec un regard vif et intéressé.",null,"28"),
M("La prise en charge de la Malnutrition aigüe modérée se fait :",["A. Unité de Nutrition Thérapeutique","B. Centre Nutritionnel de Supplémentation","C. Unité de Nutrition Thérapeutique Ambulatoire","D. Unité de nutrition Thérapeutique au centre hospitalier universitaire"],[1],"La malnutrition aiguë modérée est prise en charge au centre nutritionnel de supplémentation.",null,"29"),
M("La croissance qualitative est surveillée avec le paramètre suivant :",["A. Le périmètre crânien","B. La taille","C. Les fontanelles","D. Le poids"],[2],"La croissance qualitative (maturation) est surveillée par les fontanelles ; le périmètre crânien, la taille et le poids relèvent de la croissance quantitative.",null,"30"),
M("QG a une surface corporelle à la naissance de 0,27m2, quelle est sa surface corporelle à 3 ans",["A. 0,81m2","B. 0,54m2","C. 0,92m2","D. 1,21m2"],[0],"3 ans = 36 mois : SCN × 3 = 0,27 × 3 = 0,81 m2.",null,"31"),
M("Les propositions suivantes sont des avantages de l'allaitement exclusif pour le nouveau-né sauf une. Cochez cette proposition :",["A. Favorise la croissance harmonieuse","B. Favorise le développement cérébral","C. Favorise l'attachement à la mère","D. Favorise les infections respiratoires"],[3],"L'allaitement exclusif protège contre les infections ; il ne favorise pas les infections respiratoires.",null,"32"),
M("Les séquelles neurologiques et neurosensorielles au cours du paludisme et sont les suivantes sauf une, laquelle ?",["A. Paralysie","B. Hypotonie","C. Hypoacousie","D. Mastoïdite"],[3],"La mastoïdite n'est pas une séquelle neurologique ou neurosensorielle du paludisme.",null,"33"),
M("Tous les facteurs suivants inhibent le réflexe ocytocique chez la mère, sauf un. Cocher l'intrus",["A. La vue de son bébé","B. La douleur physique","C. Le manque de confiance en soi","D. La crise d'anxiété"],[0],"La vue du bébé stimule le réflexe ocytocique ; douleur, manque de confiance et anxiété l'inhibent.",null,"34"),
M("GH, sexe féminin, poids 12 kg présente des convulsions. Pour arrêter ces convulsions j'utilise du Diazépam. La dose maximale de Diazépam que je ne dois pas dépasser en une journée de traitement est de :",["A. 12 mg","B. 24 mg","C. 36 mg","D. 48 mg"],[2],"Dose journalière à ne pas dépasser : 3 mg/kg. Donc 1 kg → 3 mg ; 12 kg → 12 × 3 = 36 mg.",null,"35"),
M("Dame ZP vient d'accoucher son premier enfant et vous demande conseil pour avoir une bonne montée laiteuse. Je conseille à dame ZP",["A. de réduire la fréquence de tété du bébé","B. d'augmenter le nombre de tété de son bébé","C. de suivre un régime amaigrissant pour garder la ligne","D. de confier son bébé à l'aide pour mieux se reposer"],[1],"La montée laiteuse est stimulée par des tétées plus fréquentes.",null,"36"),
M("FH est de 5 mois et orphelin de mère. Pour préparer son bol de lait infantile de 180 ml, j'utilise :",["A. 7 mesurettes rase de lait","B. 6 mesurettes rase de lait","C. 5 mesurettes rase de lait","D. 4 mesurettes rase de lait"],[1],"1 mesurette → 30 ml ; Y = 180 / 30 = 6 mesurettes.",null,"37"),
M("Vous consultez l'enfant JP âgé de mois. Son Z-score poids pour l'âge est en dessous de moins 1. Cela signifie que JP :",["A. a un poids insuffisant pour son âge","B. est en surpoids pour son âge","C. est obèse pour son âge","D. a un poids normal pour son âge"],[3],"Un Z-score poids pour l'âge situé entre −1 et −2 écarts-types correspond à un poids normal ; l'insuffisance pondérale commence en dessous de −2.",null,"38"),
M("EP est âgé de 18 mois. Il souffre du Kwashiorkor et pris en charge à l'hôpital. L'allure de sa courbe de poids sous traitement décrit classiquement la forme de la lettre",["A. Y","B. M","C. V","D. W"],[2],"Sous traitement, la courbe de poids du kwashiorkor décrit la forme d'un V (perte d'œdèmes puis reprise de poids).",null,"39"),
M("Dame KJ allaite son nouveau-né depuis la naissance. Parmi les propositions suivantes relatives à l'avantage de l'allaitement pour dame KJ se trouve un intrus. Cochez l'intrus.",["A. Favorise l'hémorragie de la délivrance","B. Favorise l'attachement de KJ à son enfant","C. Favorise l'espacement des naissances","D. Favorise la contraction utérine du postpartum immédiat"],[0],"L'allaitement prévient (et non favorise) l'hémorragie de la délivrance : A est l'intrus.",null,"40"),
M("La complication redoutable à prévenir en urgence chez tout enfant sévèrement malnutri est",["A. Hypoglycémie","B. Déshydratation","C. Anémie sévère","D. Défaillance cardiaque"],[0],"À l'admission d'un enfant sévèrement malnutri, on prévient d'abord l'hypoglycémie (eau sucrée à 10 % dans l'attente du lait thérapeutique).",null,"41"),
M("L'état de mal convulsif désigne une crise convulsive qui dure plus de :",["A. 05 minutes","B. 10 minutes","C. 20 minutes","D. 30 minutes"],[3],"Réponse relevée sur la correction de l'épreuve : 30 minutes.",null,"42"),
M("Pour la reconstitution de l'eau sucrée à 10% administrée à l'enfant malnutri à l'admission, j'utilise 2 carreaux de sucre po[ur]",["A. 200 ml d'eau potable","B. 150 ml d'eau potable","C. 100 ml d'eau potable","D. 50 ml d'eau potable"],[2],"1 carreau de sucre = 5 g ; 2 carreaux = 10 g ; eau sucrée à 10 % = 10 g pour 100 ml.",null,"43"),
M("Nourrisson GG fillette de 18 mois, présente des pleurs incessants, et un refus de téter. Elle n'est pas à jour de ses vaccins. A l'examen physique, la fontanelle antérieure est bombée, et la température de 40° Celsius, poids 10 Kg. GG souffre d'une méningite purulente. GG a :",["A. 1 données au niveau de sa réalité personnelle","B. 2 données au niveau de sa réalité personnelle","C. 3 données au niveau de sa réalité personnelle","D. 4 données au niveau de sa réalité personnelle"],[2],"Données relevées sur les passages surlignés : pleurs incessants, refus de téter, température de 40° Celsius.",null,"44"),
M("Nourrisson GG fillette de 18 mois, présente des pleurs incessants, et un refus de téter. Elle n'est pas à jour de ses vaccins. A l'examen physique, la fontanelle antérieure est bombée, et la température de 40° Celsius, poids 10 Kg. GG souffre d'une méningite purulente. GG a :",["A. 4 données de dépendance","B. 5 données de dépendance","C. 6 données de dépendance","D. 7 données de dépendance"],[2],"Données de dépendance : pleurs incessants, refus de téter, absence de mise à jour des vaccins, fontanelle antérieure bombée, température de 40° Celsius, méningite purulente (6).",null,"45"),
M("GG fillette de 18 mois, présente des pleurs incessants, et un refus de téter. Elle n'est pas à jour de ses vaccins. A l'examen physique, la fontanelle antérieure est bombée, et la température de 40° Celsius, poids 10 Kg. GG souffre d'une méningite purulente. GG a :",["A. 3 données d'indépendance","B. 4 données d'indépendance","C. 5 données d'indépendance","D. 6 données d'indépendance"],[0],"Données d'indépendance : GG, fillette, 18 mois (3).",null,"46"),
M("GG fillette de 18 mois, présente des pleurs incessants, et un refus de téter. Elle n'est pas à jour de ses vaccins. A l'examen physique, la fontanelle antérieure est bombée, et la température de 40° Celsius, poids 10 Kg. GG souffre d'une méningite purulente. L'interprétation des données de GG met en évidence :",["A. Infection bactérienne des méninges et absence de protection","B. Hypertension intracrânienne fébrile et absence de protection","C. Trouble de la régulation thermique et menace sur l'intégrité physique et psychique","D. Immaturité cérébrale et cutanée et absence de protection"],[0],"Méningite purulente (infection bactérienne des méninges) et vaccination non à jour (absence de protection).",null,"47")
]}
);

